questionvariables.text:
/* 100 farms. Each row: farm ID, then grow/sold/income for each crop.
   Missing incomes are represented by "NA" in the CSV. */
crops:["Maize","Sorghum","Millet"];
grow_prob:[75,65,70];
sale_prob:[65,38,80];
base_income:[90,145,95];
income_range:[61,51,41];
make_crop(j):=block([g,s,v],
 g:if rand(100)<grow_prob[j] then 1 else 0,
 s:if g=1 and rand(100)<sale_prob[j] then 1 else 0,
 v:if s=1 then rand(income_range[j])+base_income[j] else "NA",
 [g,s,v]
);
make_farm(i):=block([a,b,c],
 a:make_crop(1),b:make_crop(2),c:make_crop(3),
 append([i],a,b,c)
);
/* Deliberately reproduce the original diagnostic reversal, while
   varying all 100 farm records and their income values. */
grow_count(j):=sum(dataset[i][3*j-1],i,1,100);
sold_count(j):=sum(dataset[i][3*j],i,1,100);
sales_total(j):=sum(if dataset[i][3*j]=1 then dataset[i][3*j+1] else 0,i,1,100);
accepted:false;
attempts:0;
while not accepted and attempts<1000 do (
 attempts:attempts+1,
 dataset:makelist(make_farm(i),i,1,100),
 ng:makelist(grow_count(j),j,1,3),
 ns:makelist(sold_count(j),j,1,3),
 totals:makelist(sales_total(j),j,1,3),
 means:makelist(totals[j]/ng[j],j,1,3),
 observed_means:makelist(totals[j]/ns[j],j,1,3),
 all_means:makelist(totals[j]/100,j,1,3),
 best_index:1,
 worst_index:1,
 observed_best:1,
 observed_worst:1,
 all_best:1,
 all_worst:1,
 for j:2 thru 3 do (
  if means[j]>means[best_index] then best_index:j,
  if means[j]<means[worst_index] then worst_index:j,
  if observed_means[j]>observed_means[observed_best] then observed_best:j,
  if observed_means[j]<observed_means[observed_worst] then observed_worst:j,
  if all_means[j]>all_means[all_best] then all_best:j,
  if all_means[j]<all_means[all_worst] then all_worst:j
 ),
 accepted:is(best_index=3 and worst_index=2
             and observed_best=2 and observed_worst=3)
);
ta_best:crops[best_index];
ta_worst:crops[worst_index];
ma_1:makelist([crops[j],is(j=best_index)],j,1,3);
ma_2:makelist([crops[j],is(j=worst_index)],j,1,3);
q2_index:rand(3)+1;
q2_crop:crops[q2_index];
ta_3:float(round(100*means[q2_index])/100);
alt_observed:observed_means[q2_index];
alt_all:all_means[q2_index];
/* Accept rounding to 2 decimal places (absolute tolerance 0.0051). */

complete_ids:sublist(makelist(i,i,1,100),lambda([k],dataset[k][4] # "NA" and dataset[k][7] # "NA" and dataset[k][10] # "NA"));
complete_n:length(complete_ids);
complete_means:if complete_n>0 then makelist(sum(if member(i,complete_ids) then dataset[i][3*j+1] else 0,i,1,100)/complete_n,j,1,3) else [0,0,0];
complete_best:1;
complete_worst:1;
if complete_n>0 then for j:2 thru 3 do (if complete_means[j]>complete_means[complete_best] then complete_best:j,if complete_means[j]<complete_means[complete_worst] then complete_worst:j);
alt_complete:if complete_n>0 then complete_means[q2_index] else -999999;

feedbackvariables.text:
correct_pair:if ans1=ta_best and ans2=ta_worst then 1 else 0;
observed_pair:if ans1=crops[observed_best] and ans2=crops[observed_worst] then 1 else 0;
all_pair:if ans1=crops[all_best] and ans2=crops[all_worst] then 1 else 0;
complete_pair:if complete_n>0 and ans1=crops[complete_best] and ans2=crops[complete_worst] then 1 else 0;

correct_mean:if is(abs(float(ans3-ta_3))<=0.0051) then 1 else 0;
observed_only:if is(abs(float(ans3-float(round(100*alt_observed)/100)))<=0.0051) then 1 else 0;
all_farms:if is(abs(float(ans3-float(round(100*alt_all)/100)))<=0.0051) then 1 else 0;
complete_only:if complete_n>0 and is(abs(float(ans3-float(round(100*alt_complete)/100)))<=0.0051) then 1 else 0;
